"""Helpers for resolving per-actuator motor speed limits.

The training env and MuJoCo inference both rate-limit position targets.  Robots
with mixed actuators should not use one global scalar limit for every joint, so
this module resolves a per-actuator vector from a scalar fallback plus optional
shell-style wildcard overrides keyed by actuator/joint name.
"""

from __future__ import annotations

from fnmatch import fnmatchcase
from typing import Any, Mapping, Sequence


def _as_mapping(value: Any) -> Mapping[str, Any]:
    if value is None:
        return {}
    if hasattr(value, "to_dict"):
        value = value.to_dict()
    if isinstance(value, Mapping):
        return value
    raise TypeError(f"expected mapping, got {type(value).__name__}")


def resolve_motor_velocity_limits(
    config: Mapping[str, Any],
    actuator_names: Sequence[str],
    *,
    default_key: str = "max_motor_velocity",
    overrides_key: str = "max_motor_velocity_by_joint",
) -> list[float]:
    """Return one velocity cap per actuator name.

    Args:
        config: Config mapping.  ``max_motor_velocity`` is the scalar fallback.
            ``max_motor_velocity_by_joint`` may be a mapping of shell-style
            wildcard patterns to numeric limits, for example ``"*_ankle": 30``.
        actuator_names: Actuator/joint names in policy action order.
        default_key: Config key for the fallback scalar.
        overrides_key: Config key for the wildcard mapping.

    Pattern order follows YAML/dict insertion order.  Later matching patterns
    override earlier ones, which makes it easy to place broad patterns first and
    more specific exceptions later.
    """
    cfg = _as_mapping(config)
    if default_key not in cfg:
        raise KeyError(f"missing required config key {default_key!r}")

    default_limit = float(cfg[default_key])
    if default_limit <= 0.0:
        raise ValueError(f"{default_key} must be > 0, got {default_limit}")

    names = [str(n) for n in actuator_names]
    limits = [default_limit for _ in names]

    overrides = cfg.get(overrides_key, None)
    if overrides is None:
        return limits
    overrides_map = _as_mapping(overrides)

    for pattern, raw_limit in overrides_map.items():
        pattern = str(pattern)
        limit = float(raw_limit)
        if limit <= 0.0:
            raise ValueError(
                f"{overrides_key}.{pattern} must be > 0, got {limit}"
            )
        for i, name in enumerate(names):
            if fnmatchcase(name, pattern):
                limits[i] = limit

    return limits


def motor_velocity_limit_map(
    config: Mapping[str, Any],
    actuator_names: Sequence[str],
) -> dict[str, float]:
    """Return a name -> resolved velocity limit mapping for logging/metadata."""
    limits = resolve_motor_velocity_limits(config, actuator_names)
    return {str(name): float(limit) for name, limit in zip(actuator_names, limits)}
